/* ---------- deterministic abstract "art" per project (fallback when no real image) ---------- */

const palettes = [
  ["#FF6B6B", "#FFB870", "#1A1418"],
  ["#8C7CF0", "#4ADEDE", "#14121F"],
  ["#FFB870", "#FF6B6B", "#1F1512"],
  ["#4ADEDE", "#8C7CF0", "#0F1A1D"],
  ["#FF9C6B", "#FF6BA8", "#1A1216"],
  ["#7CF0C4", "#8C7CF0", "#101A17"],
];

function hashStr(s) {
  let h = 0;
  for (let i = 0; i < s.length; i++) h = (h * 31 + s.charCodeAt(i)) >>> 0;
  return h;
}

function ArtCanvas({ id, title }) {
  const h = hashStr(id + title);
  const pal = palettes[h % palettes.length];
  const seed1 = h % 100;
  const seed2 = (h >> 3) % 100;
  const seed3 = (h >> 6) % 100;
  const rot = (h % 40) - 20;
  const shape = h % 3;

  return (
    <svg
      viewBox="0 0 400 300"
      style={{ width: "100%", height: "100%", display: "block" }}
      preserveAspectRatio="xMidYMid slice"
    >
      <defs>
        <radialGradient id={`g1-${id}`} cx={`${seed1}%`} cy={`${seed2}%`} r="75%">
          <stop offset="0%" stopColor={pal[0]} stopOpacity="0.9" />
          <stop offset="100%" stopColor={pal[2]} stopOpacity="0" />
        </radialGradient>
        <radialGradient id={`g2-${id}`} cx={`${seed3}%`} cy={`${100 - seed1}%`} r="65%">
          <stop offset="0%" stopColor={pal[1]} stopOpacity="0.85" />
          <stop offset="100%" stopColor={pal[2]} stopOpacity="0" />
        </radialGradient>
        <filter id={`blur-${id}`}>
          <feGaussianBlur stdDeviation="18" />
        </filter>
      </defs>
      <rect width="400" height="300" fill={pal[2]} />
      <g filter={`url(#blur-${id})`}>
        <rect width="400" height="300" fill={`url(#g1-${id})`} />
        <rect width="400" height="300" fill={`url(#g2-${id})`} />
      </g>
      <g opacity="0.5" transform={`rotate(${rot} 200 150)`}>
        {shape === 0 && (
          <circle cx={200 + (seed1 - 50)} cy={150 + (seed2 - 50)} r={70 + (seed3 % 40)} fill="none" stroke={pal[1]} strokeWidth="1" />
        )}
        {shape === 1 && (
          <rect x={120 - seed1 / 3} y={90 - seed2 / 3} width="160" height="160" fill="none" stroke={pal[0]} strokeWidth="1" />
        )}
        {shape === 2 && (
          <polygon
            points={`200,${90 - seed3 / 3} ${310},${210} ${90},${210}`}
            fill="none"
            stroke={pal[1]}
            strokeWidth="1"
          />
        )}
      </g>
      <g opacity="0.16">
        <rect width="400" height="300" fill="none" />
        {Array.from({ length: 6 }).map((_, i) => (
          <line key={i} x1={0} y1={i * 60} x2={400} y2={i * 60} stroke={pal[1]} strokeWidth="0.5" />
        ))}
      </g>
    </svg>
  );
}

/* Renders a real image when the project has one, otherwise falls back to generated art */
function ProjectVisual({ project }) {
  if (project.image) {
    return (
      <img
        src={project.image}
        alt={project.title}
        loading="lazy"
        decoding="async"
        style={{ width: "100%", height: "100%", objectFit: "cover", display: "block" }}
      />
    );
  }
  return <ArtCanvas id={project.id} title={project.title} />;
}

